// Validate and create training job.
const body = $json.body || {};

if (!body.dataset_id) throw new Error('dataset_id required');

const config = {
  lora_rank: body.lora_rank || 8,
  lora_alpha: body.lora_alpha || 16,
  learning_rate: body.learning_rate || '1e-4',
  epochs: body.epochs || 3,
  batch_size: body.batch_size || 4,
  max_seq_length: body.max_seq_length || 2048,
  min_quality: body.min_quality || 0.6
};

return [{
  json: {
    dataset_id: body.dataset_id,
    base_model: body.base_model || 'mlx-community/Qwen2.5-Coder-7B-Instruct-4bit',
    adapter_type: body.adapter_type || 'lora',
    config
  }
}];

// Write JSONL to temp file and invoke train-lora.sh.
// In production, this would use SSH Execute or a dedicated training worker.
const exportResult = $json;
const job = $('Create Job Record').first().json;
const jobId = Array.isArray(job) ? job[0]?.id : job.id;
const config = $('Validate & Configure').first().json.config;
const baseModel = $('Validate & Configure').first().json.base_model;

// For local execution: write JSONL to /tmp
const fs = require('fs');
const dataDir = `/tmp/aisha-training/${jobId}`;
fs.mkdirSync(dataDir, { recursive: true });

if (exportResult.sft_jsonl) {
  fs.writeFileSync(`${dataDir}/train.jsonl`, exportResult.sft_jsonl);
}
if (exportResult.dpo_jsonl) {
  fs.writeFileSync(`${dataDir}/dpo.jsonl`, exportResult.dpo_jsonl);
}

// Prepare training command (would be executed via SSH or local shell)
const trainCmd = [
  './scripts/ai/train-lora.sh',
  `--data ${dataDir}/train.jsonl`,
  `--output ${dataDir}/output`,
  `--model ${baseModel}`,
  `--rank ${config.lora_rank}`,
  `--alpha ${config.lora_alpha}`,
  `--epochs ${config.epochs}`,
  `--lr ${config.learning_rate}`,
  `--batch ${config.batch_size}`,
  `--max-seq ${config.max_seq_length}`
].join(' ');

return [{
  json: {
    job_id: jobId,
    data_dir: dataDir,
    sft_count: exportResult.sft_count || 0,
    dpo_count: exportResult.dpo_count || 0,
    train_command: trainCmd,
    status: 'ready_for_training'
  }
}];

// Return job status.
const prep = $json;

return [{
  json: {
    success: true,
    job_id: prep.job_id,
    status: prep.status,
    sft_examples: prep.sft_count,
    dpo_examples: prep.dpo_count,
    train_command: prep.train_command,
    message: `Training job ${prep.job_id} prepared with ${prep.sft_count} SFT + ${prep.dpo_count} DPO examples. Execute train_command on Apple Silicon host.`
  }
}];
